package lk.ac.sliit.ridelink.driver.presentation.controller;
import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lk.ac.sliit.ridelink.driver.application.dto.request.UpdateDriverProfileRequest; import lk.ac.sliit.ridelink.driver.application.dto.response.DriverProfileResponse; import lk.ac.sliit.ridelink.driver.application.port.in.DriverVehicleUseCase; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/admin/drivers") @Tag(name="Driver administration") @SecurityRequirement(name="bearerAuth") public class AdminDriverController {private final DriverVehicleUseCase service;public AdminDriverController(DriverVehicleUseCase s){service=s;}@GetMapping("/{id}")public DriverProfileResponse get(@PathVariable UUID id){return service.getProfile(id);}@PatchMapping("/{id}")public DriverProfileResponse update(@PathVariable UUID id,@Valid @RequestBody UpdateDriverProfileRequest r){return service.updateProfile(id,r);}}
